import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';
import '../../../../l10n/gen/app_localizations.dart';
import '../bloc/registration_bloc.dart';

class AcceptInvitationPage extends StatefulWidget { const AcceptInvitationPage({required this.token,super.key}); final String token; @override State<AcceptInvitationPage> createState()=>_AcceptInvitationPageState(); }
class _AcceptInvitationPageState extends State<AcceptInvitationPage>{ final name=TextEditingController(),password=TextEditingController(); @override void initState(){super.initState();WidgetsBinding.instance.addPostFrameCallback((_)=>context.read<RegistrationBloc>().add(InvitationLoaded(widget.token)));} @override void dispose(){name.dispose();password.dispose();super.dispose();} @override Widget build(BuildContext c){final l=AppLocalizations.of(c);return Scaffold(appBar:AppBar(title:Text(l.invitationTitle)),body:BlocBuilder<RegistrationBloc,RegistrationState>(builder:(c,s){if(s.status==RegistrationStatus.loading)return const Center(child:CircularProgressIndicator());if(s.status==RegistrationStatus.failure)return Center(child:Text(l.invitationExpired));return ListView(padding:const EdgeInsetsDirectional.all(20),children:[Text(l.invitationRoleLabel),Text(s.invitation?.role.name??''),const SizedBox(height:16),TextField(controller:name,decoration:InputDecoration(labelText:l.registerNameLabel)),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:InputDecoration(labelText:l.loginPasswordLabel)),const SizedBox(height:20),FilledButton(onPressed:()=>context.read<RegistrationBloc>().add(InvitationAccepted(token:widget.token,password:password.text,displayName:name.text)),child:Text(l.invitationAccept))]));}));}}
